INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `VoiceOverPriorityID`, `SoundKitID1`, `SoundKitID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES ('','I am told the farms of Westfall once supplied a bounty of crops for Stormwind. But now, the soil is barren and most of the farmers have fled.\r\n\r\nOn behalf of Darnassus I would like to offer my aid in replenishing this land. Will you assist me?',301857,0,0,0,256,0,4,0,0,0,0,0,0,0,0,71037);
INSERT INTO `hotfix_data` (`Id`,`UniqueId`,`TableHash`,`RecordId`,`Status`,`VerifiedBuild`) VALUES
(2105600,1397825600,35137211,301857,1,71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (292961,'ruRU','Профессии делятся на две главные категории: основные и вспомогательные.\r\n\r\nМожно получить только две основные профессии. В любой момент разрешено отказаться от одной из профессий, но все полученные знания при этом будут утрачены. Если же вернуться к забытой профессии, придется изучать все с нуля и собирать рецепты повторно.\r\n\r\nУ вспомогательных профессий нет такого ограничения. Цель этих навыков – основы выживания без чужой помощи. Все вспомогательные профессии можно прокачивать одновременно, но они почти не будут приносить прибыли.','Профессии делятся на две главные категории: основные и вспомогательные.\r\n\r\nМожно получить только две основные профессии. В любой момент разрешено отказаться от одной из профессий, но все полученные знания при этом будут утрачены. Если же вернуться к забытой профессии, придется изучать все с нуля и собирать рецепты повторно.\r\n\r\nУ вспомогательных профессий нет такого ограничения. Цель этих навыков – основы выживания без чужой помощи. Все вспомогательные профессии можно прокачивать одновременно, но они почти не будут приносить прибыли.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (299683,'ruRU','Здравствуй! Рад встрече.$B$BУвы, я с печальными вестями: Даларан нуждается в помощи королевств Альянса.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (300665,'ruRU','','Я руковожу делами деревни Шен\'дар, и здесь очень многое нужно держать под контролем. Бандиты, сектанты и прочие неожиданные происшествия – чтобы эта деревня держалась на плаву, приходится немало потрудиться.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (309779,'ruRU','На сегодня боев не назначено. Орда и Альянс убивают друг друга по полям бесплатно, а могли бы на моей арене за хороший гонорар! Поди их пойми.\r\n\r\nЗайдешь попозже. Когда дела живее пойдут.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (310771,'ruRU','Сейчас покажу кое-что реально жуткое!','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (317087,'ruRU','Поможешь в бою на островах Черного Копья?','Поможешь в бою на островах Черного Копья?',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (322129,'ruRU','От панели исходит сильный жар. В приемнике консоли размещена посеребренная чаша, внутренняя поверхность которой покрыта сажей и почерневшими осколками.','От панели исходит сильный жар. В приемнике консоли размещена посеребренная чаша, внутренняя поверхность которой покрыта сажей и почерневшими осколками.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (324570,'ruRU','Превосходно. Отправляйся к источнику – там чародейская магия наиболее сильна. Так как в мире почти не осталось истинных высокорожденных чародеев, это твой лучший шанс очистить сферу после такого долгого периода застоя.\r\n\r\nЯ заканчиваю изучение фолианта и смогу завершить клинок, как только ты принесешь все необходимое. Похоже, мы еще увидим этот шедевр в его первозданном виде.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327773,'ruRU','<Когда вы подходите к этому саблезубу, он угрожающе рычит. Его длинный хвост молотит по земле.\r\n\r\nОн ощеривается и вонзает когти в мягкую землю. Похоже, нрав у него такой же поистине грозный.\r\n\r\nСаблезуб осторожно обнюхивает вас, а затем, немного погодя, фыркает. Кажется, его впечатлило, что вы не отступили.\r\n\r\nПохоже, ваша решимость, которую в вас почувствовал саблезуб, ему по нраву. Он признает вас соратником и достойным наездником, если вы выберете его.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327777,'ruRU','','<Когда вы приближаетесь, огромная кошка вытягивает длинные изящные лапы, не издавая ни звука.>',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327778,'ruRU','','<Когда вы приближаетесь, огромная кошка вытягивает длинные изящные лапы, не издавая ни звука.\r\n\r\nСаблезуб трясет головой. Доспехи сидят на нем плотно, позволяя двигаться совершенно беззвучно.\r\n\r\nОн внимательно наблюдает за вами, выпуская и втягивая острые когти. Молчаливый саблезуб изучает вас и принюхивается.\r\n\r\nСлегка склонив голову в знак приветствия, он выказывает уважение к вашим свершениям. Похоже, он счел бы вас достойным соратником и всадником, если бы вы решили выбрать его.>',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327780,'ruRU','','<Когда вы приближаетесь, саблезуб поворачивает к вам свою огромную голову.\r\n\r\nВы чувствуете на себе его пронзительный оценивающий взгляд из-под забрала сияющего шлема. Сам зверь замер, и только мягкий ветер Тельдрассила слегка теребит его шерсть. Кажется, он чувствует, что вы возмужали и на вашу долю выпала масса испытаний и приключений.\r\n\r\nВыдержав паузу, он глухо рычит и склоняет голову, закованную в броню.\r\n\r\nПохоже, этот саблезуб готов стать вашим верным спутником и надежным скакуном, если вы его выберете.>',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327782,'ruRU','<Когда вы подходите к этому механодолгоногу, его выхлопные трубы начинают поблескивать и выпускают газ, который кажется чуть менее плотным, чем у соседних машин. Вы слышите жужжание: похоже, в вашем присутствии механизм перенастраивает параметры. Этикетка на механодолгоноге:\r\n\r\n\"Меха-титановый эко-долгоног 9000! Теперь с удлиненными щитками на крыльях и экологичными демпферами выхлопной трубы\".>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327783,'ruRU','<Этикетка на механодолгоноге:\r\n\r\nСкороног \"4в4рия\" 3X 4000! Теперь с новыми датчиками радиации и распылителями для дезактивации!>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327784,'ruRU','<Механодолгоног поворачивает голову, чтобы взглянуть на вас. При вашем приближении на его выхлопной трубе загорается и начинает мигать огонек, а затем на шее и ногах открываются специальные вентиляционные отверстия, выпуская легкую дымку. Этикетка на механодолгоноге:\r\n\r\nСкороног \"4в4рия\" 3X 4000! Теперь с новыми датчиками радиации и распылителями для дезактивации!>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327788,'ruRU','<Когда вы подходите к этому барану, он сначала с интересом наблюдает за вами, а затем опускает голову, демонстрируя рога. Он долго и пристально смотрит на вас, издавая вызывающее фырканье. Затем баран расслабляется, и вы видите по его глазам, что он вас узнал.\r\n\r\nОн снова фыркает и стряхивает снег со своей закованной в броню головы. На его мощных рогах поблескивают новые зазубрины и вмятины – следы битв, в которых он победил после вашей последней встречи.\r\n\r\nЭтот свирепый баран словно чувствует вашу решимость и одобряет ее. Он готов принять вас как всадника.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327796,'ruRU','<Ящер поворачивается и устремляет на вас взгляд ярко-оранжевых глаз.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327799,'ruRU','<Когда вы подходите к этому кодо, он стоит, гордо выпрямившись. Удары его мощных лап сотрясают землю. Увидев вас, кодо довольно фыркает.\r\n\r\nПохоже, этот некогда робкий зверь обрел уверенность в себе и гордится своей силой и бесстрашием.\r\n\r\nВидно, что ваше присутствие его воодушевляет: он с гордостью стал бы вашим верным соратником и провез бы вас на спине по всему миру.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327800,'ruRU','<Заметив ваше приближение, этот кодо с очень мощной шеей поворачивает голову и пристально смотрит на вас проницательным взглядом из-под шлема. Похоже, время ничуть не умерило его отважный и дерзкий нрав.\r\n\r\nЕго рог и шкуру покрывают длинные глубокие шрамы. Очевидно, что за время вашей разлуки он выходил победителем из каждой схватки – будь то бой с врагом или состязание с другом.\r\n\r\nОценив вас взглядом, он успокаивается, видя, что вы не отступили. Похоже, его впечатлила ваша смелость, а также враги и испытания, с которыми вам удалось справиться в ходе долгих странствий. Он с радостью признает вас наездником и станет вашим верным соратником.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327801,'ruRU','<Подходя к буреногу, вы замечаете, что птица царапает когтями влажную землю. Стоит вам приблизиться, как она замирает – возможно, чувствуя в вас что-то знакомое.\r\n\r\nБуреног издает нежное воркотание, с интересом осматривая вас. Ему явно любопытно, кто вы и где побывали. Похоже, его впечатлило то, какие трудности вы преодолели и сколь долгим был ваш путь сюда.\r\n\r\nВы понравились этому кроткому буреногу. Он с радостью отправится в путешествие с таким наездником и соратником.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327802,'ruRU','<Когда вы приближаетесь к этому буреногу, птица, узнав вас, издает приветственную трель и будто подскакивает в предвкушении чего-то интересного. Хотя буреног уже вырос, он сохранил окраску, свойственную детенышам, что довольно необычно.\r\n\r\nОн замирает, прекратив суетливые движения и устремив на вас взгляд золотистых глаз. А через мгновение издает мягкую трель, явно впечатленный тем, какие серьезные испытания вам удалось преодолеть.\r\n\r\nВскоре буреног мягко щелкает клювом и издает еще несколько трелей. Ваша решимость впечатлила его. Он не против отправиться в путешествие с таким другом и наездником.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327803,'ruRU','<Когда вы приближаетесь к буреногу, он внимательно смотрит на вас золотистыми глазами и через мгновение издает приветственную трель.\r\n\r\nС тех пор как вы расстались, этот буреног повидал немало боев: на его ногах и клюве видны следы сражений, а на полированной броне заметны признаки износа.\r\n\r\nНаверное, вы понравились этому бесстрашному буреногу. Он мечтает путешествовать по новым мирам с таким другом и наездником.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327804,'ruRU','<Даже сквозь забрало шлема вы чувствуете, как волк изучает вас взглядом.>','<Волк оборачивается, когда вы подходите. Вы ощущаете на себе взгляд его внимательных глаз, скрытых под забралом шлема. Зверь осторожно обнюхивает вас и, узнав, издает тихое, но вполне дружелюбное урчание.\r\n\r\n\r\nОн выпрямляется, словно желая продемонстрировать тяжелую броню, облачающую его мощное тело. Полированный металл блестит, несмотря на слой дуротарской пыли, нанесенной на него теплыми ветрами.\r\n\r\nВы испытываете необъяснимый прилив чувств, видя, что волку пришлась по нраву ваша отвага. Этот зверь готов обрести в вас наездника и верного друга.>',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327805,'ruRU','<При вашем приближении волк встряхивает своей крупной головой. Его доспехи мягко поблескивают, выделяясь на фоне пепельной шерсти зверя.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327806,'ruRU','<Волк стоит, уверенно выпрямившись даже под тяжестью доспехов.>','<Подобно тому, как свежесрубленная кедровая древесина со временем меняет цвет с красноватого на серый, так и шерсть этого лесного волка изменилась с возрастом. Его некогда неуемный нрав стал более сдержанным, а взгляд сосредоточенным. Он уверенно и крепко стоит на ногах, и даже тяжелые доспехи, похоже, не доставляют ему неудобства.\r\n\r\nКогда вы подходите ближе, он дружелюбно помахивает длинным хвостом и приветственно поскуливает. В прорези укрепленного магией забрала шлема вы видите блеск его решительных глаз – жажда приключений в нем ничуть не угасла.\r\n\r\nЧерез мгновение волк принимается воодушевленно рычать. Вы чувствуете, что он восхищается вашим духом искателя приключений и впечатлен испытаниями, которые вы преодолели. Волк готов с радостью принять вас как всадника и верного спутника.>',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (327809,'ruRU','Ага, в таверне сидит гостья с Заоблачного пика. Она наверняка поможет тебе с духовными наставлениями... или чем там еще занимаются шаманы. Как же ее зовут?.. Ингол? Ир... Ингрид! Да, ее имя – Ингрид.','Ага, в таверне сидит гостья с Заоблачного пика. Она наверняка поможет тебе с духовными наставлениями... или чем там еще занимаются шаманы. Как же ее зовут?.. Ингол? Ир... Ингрид! Да, ее имя – Ингрид.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328220,'ruRU','А, подстричься хочешь? Мне бы к цирюльнику тоже сходить не помешало. Может, загляну после смены!\r\n\r\nПарикмахерская находится к северо-западу от входа в Стальгорн.','А, подстричься хочешь? Мне бы к цирюльнику тоже сходить не помешало. Может, загляну после смены!\r\n\r\nПарикмахерская находится к северо-западу от входа в Стальгорн.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328221,'ruRU','Не волнуйся, парикмахерская совсем рядом – к северо-западу от входа в Стальгорн.\r\n\r\nТам тебя мигом приведут в порядок!','Не волнуйся, парикмахерская совсем рядом – к северо-западу от входа в Стальгорн.\r\n\r\nТам тебя мигом приведут в порядок!',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328240,'ruRU','Хочешь обновить узоры на лице или подготовиться к охоте? Лучшего места, чем парикмахерская, для этого не найти.\r\n\r\nОна расположена на Террасе Торговцев, рядом с аукционом.','Хочешь обновить узоры на лице или подготовиться к охоте? Лучшего места, чем парикмахерская, для этого не найти.\r\n\r\nОна расположена на Террасе Торговцев, рядом с аукционом.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328241,'ruRU','Прежде чем входить в храм, нужно привести себя в порядок. Загляни в парикмахерскую – она на Террасе Торговцев.','Прежде чем входить в храм, нужно привести себя в порядок. Загляни в парикмахерскую – она на Террасе Торговцев.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328287,'ruRU','Рога затупились? На нижнем ярусе центральной вершины есть гоблин, который тебе поможет.','Рога затупились? На нижнем ярусе центральной вершины есть гоблин, который тебе поможет.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328288,'ruRU','Если хочешь подстричь гриву, загляни на нижний уступ напротив аукционистов.','Если хочешь подстричь гриву, загляни на нижний уступ напротив аукционистов.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328594,'ruRU','<Изнуренный человек бормочет себе под нос что-то неразборчивое.>','<Изнуренный человек бормочет себе под нос что-то неразборчивое.>',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328596,'ruRU','А? Что?.. Да... Да... сбежал. Я сбежал. Да... Я... Я король Штормграда! Вариан Ринн!','А? Что?.. Да... Да... сбежал. Я сбежал. Да... Я... Я король Штормграда! Вариан Ринн!',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328598,'ruRU','Что? Да как ты смеешь! Я... ну да, конечно, король!\r\n\r\nВедь так? Руперт... мой славный Руперт... он принес мне клятву верности через решетку камеры. Поклялся служить до скончания времен! Значит, я король!\r\n\r\nДа... да, конечно. Я Руперт. Нет, постой... Я король! Руперт – мой слуга. Очень хороший слуга.','Что? Да как ты смеешь! Я... ну да, конечно, король!\r\n\r\nВедь так? Руперт... мой славный Руперт... он принес мне клятву верности через решетку камеры. Поклялся служить до скончания времен! Значит, я король!\r\n\r\nДа... да, конечно. Я Руперт. Нет, постой... Я король! Руперт – мой слуга. Очень хороший слуга.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328600,'ruRU','Ах да, Руперт. Мой славный Руперт. Он... помог мне сбежать, понимаешь. Отвлек нагу, пока я карабкался по утесу. А потом я прыгнул навстречу свободе. Да, прыгнул.\r\n\r\nА потом нага ударила меня... о, как же сильно она меня ударила. Требовала, чтобы я сказал, куда ушел король...\r\n\r\nЯ... нет, постой, мне удалось сбежать... Это Руперта схватили. Я сорвался со скалы в воду. Я... погоди... было столько крови. А потом... тьма.','Ах да, Руперт. Мой славный Руперт. Он... помог мне сбежать, понимаешь. Отвлек нагу, пока я карабкался по утесу. А потом я прыгнул навстречу свободе. Да, прыгнул.\r\n\r\nА потом нага ударила меня... о, как же сильно она меня ударила. Требовала, чтобы я сказал, куда ушел король...\r\n\r\nЯ... нет, постой, мне удалось сбежать... Это Руперта схватили. Я сорвался со скалы в воду. Я... погоди... было столько крови. А потом... тьма.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (328602,'ruRU','Нага... ведьма. От нее пахло морской водой и гнилью... она причинила мне... столько боли. О, мой повелитель... вы упали с такой высоты... на скалы внизу...\r\n\r\nНет, постой... это я упал с такой высоты. Я... сбежал... Я...\r\n\r\n<Человек отворачивается и снова начинает бессвязно бормотать.>','Нага... ведьма. От нее пахло морской водой и гнилью... она причинила мне... столько боли. О, мой повелитель... вы упали с такой высоты... на скалы внизу...\r\n\r\nНет, постой... это я упал с такой высоты. Я... сбежал... Я...\r\n\r\n<Человек отворачивается и снова начинает бессвязно бормотать.>',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329302,'ruRU','Укрытые в своей горной твердыне, они редко покидали пределы заснеженных перевалов Дун Морога.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329312,'ruRU','Правит им юный король Андуин Ринн.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329336,'ruRU','Разобщенные и разрозненные племена объединяла лишь ненависть к заклятым врагам, коварным разбойникам-кентаврам.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329728,'ruRU','<Неподвижно лежащее тело Дикого бога прозрачно и неосязаемо, словно вот-вот растворится в воздухе. Когда вы подходите ближе, бог слегка вздрагивает и начинает следить за вами стекленеющим взглядом.>','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329730,'ruRU','Отойди назад, смертное создание. Я сотворю чары, которые позволят тебе увидеть то, что видел я...','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329731,'ruRU','Нет, Ве\'хан! Не делай этого! Ты же защитник горы. Не нарушай свою клятву!','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329732,'ruRU','Чего стоят клятвы, если нас предают те, кому мы служим?! Пойми напоследок, божок: наш культ силен. Мы вернем то, что у нас забрали!','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329733,'ruRU','Нет, постой... Стой!.. А-а-а!','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329734,'ruRU','Да, вот она... Сила! Древняя сила возвращается ко мне. Теперь я... несокрушим!','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329736,'ruRU','Даже самые слабые из Древних богов полны могучей энергии. Такая мощь не должна попадать в руки смертных.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329737,'ruRU','Возвращайся к Блеску Звезд и расскажи ему все, смертное дитя.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329738,'ruRU','','Я полечу на вершину, как только восстановлю силы. Постараюсь узнать, что случилось с другими Дикими богами. Береги себя, $n.',71037);
